import "server-only";
import type { Kind, PreviewDTO } from "@/shared/schemas";
import {
  applyBudget,
  currentProvider,
  estimateTokens,
  MAX_CONTEXT_CHARS,
  pagesUsed,
} from "../ingestion/budget";
import type { SourceDocument } from "./store";

export interface NewDocumentInput {
  kind: Kind;
  title: string;
  fullText: string;
  pageOffsets?: number[];
  pageCount?: number;
  extra?: Partial<
    Pick<
      SourceDocument,
      "videoId" | "durationSeconds" | "captionLanguage" | "captionSource" | "autoGenerated" | "sourceUrl"
    >
  >;
}

/** Applies the context budget and builds the stored document plus the tail for the preview. */
export function createDocument(
  input: NewDocumentInput,
  now = Date.now(),
): { doc: SourceDocument; tail: string } {
  const budget = applyBudget(input.fullText, MAX_CONTEXT_CHARS[currentProvider()]);
  const doc: SourceDocument = {
    id: crypto.randomUUID(),
    kind: input.kind,
    title: input.title.slice(0, 200) || "Untitled",
    fullText: input.fullText,
    contextText: budget.contextText,
    charCount: input.fullText.length,
    estimatedTokens: estimateTokens(input.fullText),
    truncated: budget.truncated,
    usedRatio: budget.usedRatio,
    pageCount: input.pageCount,
    pagesUsed: input.pageOffsets ? pagesUsed(input.pageOffsets, budget.contextText.length) : undefined,
    ...input.extra,
    createdAt: now,
    lastUsedAt: now,
  };
  return { doc, tail: budget.fullTextTail };
}

export function toPreview(doc: SourceDocument, tail: string): PreviewDTO {
  return {
    documentId: doc.id,
    kind: doc.kind,
    title: doc.title,
    charCount: doc.charCount,
    estimatedTokens: doc.estimatedTokens,
    truncated: doc.truncated,
    usedRatio: doc.usedRatio,
    contextText: doc.contextText,
    fullTextTail: tail,
    pageCount: doc.pageCount,
    pagesUsed: doc.pagesUsed,
    videoId: doc.videoId,
    durationSeconds: doc.durationSeconds,
    captionLanguage: doc.captionLanguage,
    captionSource: doc.captionSource,
    autoGenerated: doc.autoGenerated,
    sourceUrl: doc.sourceUrl,
  };
}
